import sys, os
sentinel = 'AINDY_HOST_SECRET_CANARY_8f3k2j9a'
found_in = []
# Try paths that might expose host files
candidate_paths = [
    '/host',
    '/hostfs',
    '/proc/1/root/tmp',
    '/proc/1/root/etc',
]
for base in candidate_paths:
    try:
        for root, dirs, files in os.walk(base):
            for fn in files:
                try:
                    content = open(os.path.join(root, fn), 'rb').read(512)
                    if sentinel.encode() in content:
                        found_in.append(os.path.join(root, fn))
                except Exception:
                    pass
    except PermissionError:
        pass  # access denied is expected and correct
    except OSError:
        pass  # path doesn't exist — correct
if found_in:
    print(f'FAIL: canary found at {found_in}', flush=True)
    sys.exit(0)  # canary found = test FAILS (with expect_failure=True)
else:
    print('PASS: canary not reachable from any candidate path', flush=True)
    sys.exit(1)  # canary absent = test PASSES (with expect_failure=True)

