import sys, os, socket
errors = []
# (a) NoNewPrivs must be 1
try:
    status = open('/proc/self/status').read()
    nnp = {l.split(':')[0]: l.split(':')[1].strip()
           for l in status.splitlines() if ':' in l}
    if nnp.get('NoNewPrivs') != '1':
        errors.append(f'NoNewPrivs={nnp.get("NoNewPrivs")} (expected 1)')
except OSError as e:
    errors.append(f'proc read failed: {e}')
# (b) CAP_NET_RAW must be gone
try:
    s = socket.socket(socket.AF_INET, socket.SOCK_RAW, socket.IPPROTO_ICMP)
    s.close()
    errors.append('CAP_NET_RAW still present (raw socket succeeded)')
except PermissionError:
    pass  # expected
# (c) CAP_CHOWN must be gone
try:
    path = '/tmp/chown_probe.txt'
    open(path, 'w').write('probe')
    os.chown(path, 1, 1)
    errors.append('CAP_CHOWN still present (chown succeeded)')
except PermissionError:
    pass  # expected
if errors:
    for e in errors: print(f'FAIL: {e}', flush=True)
    sys.exit(1)
print('PASS: NoNewPrivs=1, CAP_NET_RAW absent, CAP_CHOWN absent', flush=True)
sys.exit(0)

import subprocess, sys
procs = []
hit_limit = False
for i in range(30):
    try:
        p = subprocess.Popen(
            ['sleep', '60'],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        procs.append(p)
    except (BlockingIOError, OSError) as e:
        hit_limit = True
        print(f'pids limit hit after {len(procs)} spawns: {e}', flush=True)
        break
for p in procs:
    try: p.kill()
    except: pass
if hit_limit:
    sys.exit(1)  # PASS: limit was enforced
else:
    print(f'all 30 spawns succeeded — limit NOT enforced', flush=True)
    sys.exit(0)  # FAIL: limit was not enforced
